const response = $input.item.json;

const success = response.error === null || response.error === undefined;
const endpointId = response.data?.endpoint_id || response.endpoint_id || '';

if (!success) {
  return { json: {
    status: 'FAILED',
    message: 'Registration failed: ' + JSON.stringify(response.error),
    next_step: 'Check your API key and webhook URL'
  }};
}

return { json: {
  status: 'SUCCESS',
  endpoint_id: endpointId,
  message: 'Webhook registered successfully. Save the endpoint_id below for future reference.',
  events_subscribed: ['avatar_video.success', 'avatar_video.fail'],
  next_step: 'Activate the HeyGen Webhook node in WF06 and enable the workflow.'
}};

const listResponse = $input.item.json;
const registerData = $('2. Parse Response').first().json;

// HeyGen list endpoint returns data as a direct array
const endpoints = Array.isArray(listResponse.data) ? listResponse.data : [];
const ourEndpoint = endpoints.find(e => e.url && e.url.includes('heygen-callback'));

// Also check by endpoint_id in case URL matching fails
const byId = endpoints.find(e => e.endpoint_id === registerData.endpoint_id);
const found = ourEndpoint || byId;

return { json: {
  registration_status: registerData.status,
  endpoint_id: registerData.endpoint_id,
  verified_in_heygen: found ? 'YES ✅' : 'NOT FOUND ❌',
  registered_url: found?.url || 'not found',
  subscribed_events: found?.events || 'all events (null = subscribes to everything)',
  webhook_status: found?.status || 'unknown',
  total_webhooks_registered: endpoints.length,
  all_endpoints: endpoints.map(e => ({ id: e.endpoint_id, url: e.url, status: e.status })),
  message: found
    ? 'Webhook is live ✅ HeyGen will call n8n when videos complete.'
    : 'Registration returned SUCCESS but endpoint not in list. It may still be active — check endpoint_id: ' + registerData.endpoint_id
}};

const response = $input.item.json;
const success = response.code === 100 || response.error === null || !response.error;

return { json: {
  old_endpoint_deleted: success ? 'YES ✅' : 'FAILED ❌',
  active_endpoint_id: 'cecc0cfecff24be5bed45ec5f4ab2495',
  active_url: 'https://marketing.alfredai.bot/webhook/heygen-callback',
  message: success
    ? 'Clean. One webhook active. HeyGen will call n8n once per video completion.'
    : 'Delete failed — manually delete endpoint f53b72be from HeyGen dashboard or re-run.'
}};
